// Bridges OpenNext's `CloudflareEnv` global to the bindings generated by
// `wrangler types` into worker-configuration.d.ts (run `npm run cf-typegen`
// after changing wrangler.jsonc). Runtime secrets are set from `.env`
// locally and via `wrangler secret put` in production, so they aren't in
// wrangler.jsonc and must be declared here.

interface CloudflareEnv extends Cloudflare.Env {
  /** OAuth web client id for signing in with Google. */
  GOOGLE_OAUTH_CLIENT_ID: string;
  /** OAuth web client secret (server-side only). */
  GOOGLE_OAUTH_CLIENT_SECRET: string;
  /** Secret that signs the session cookie. Required: with none, signing in is refused. */
  SESSION_SECRET: string;
  /** Secret that signs scan tokens. Required: with none, scans are refused. */
  SCAN_SECRET: string;
  /**
   * Public origin, e.g. https://plumbline.apps.mrida.ng. Optional; derived
   * from the request when unset (local dev).
   */
  APP_URL?: string;
  /**
   * The GitHub App: its numeric id, its URL name, its OAuth client id and
   * secret, its private key (PKCS#1 or PKCS#8 PEM) and the secret GitHub signs
   * webhooks with. All optional; GitHub integration is off until all are set.
   */
  GITHUB_APP_ID?: string;
  GITHUB_APP_SLUG?: string;
  GITHUB_CLIENT_ID?: string;
  GITHUB_CLIENT_SECRET?: string;
  GITHUB_PRIVATE_KEY?: string;
  GITHUB_WEBHOOK_SECRET?: string;
  /** The VAPID private key notifications are signed with; without it they are off. */
  VAPID_PRIVATE_KEY?: string;
  /** The Cloudflare plan, `free` (the default) or `paid`; sets the limits of the server-side checks. */
  WORKERS_PLAN?: string;
}
